package org.eink.inkprobe.notebook;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;

/** Production Android permission coordination and per-document site consent, with explicit OS/UI fakes. */
public final class NotebookBrowserMediaTest {
    private static String code(String name) throws Exception {
        String source = new String(Files.readAllBytes(Paths.get("app/src/main/java/org/eink/inkprobe/notebook/" + name + ".java")), StandardCharsets.UTF_8);
        return source.substring(source.indexOf("/**")).replace("final class " + name, "static final class " + name);
    }
    public static void main(String[] args) throws Exception {
        String fixture = String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;import java.util.function.*;public class BrowserMediaFixture {",
            "static class Manifest {static class permission {static final String RECORD_AUDIO=\"android.permission.RECORD_AUDIO\";}}static class PackageManager {static final int PERMISSION_GRANTED=0;}",
            "static class Activity {static final int MODE_PRIVATE=0;boolean granted;int requests;final Pref prefs=new Pref();int checkSelfPermission(String s){return granted?0:-1;}Pref getSharedPreferences(String n,int m){return prefs;}void requestPermissions(String[] p,int code){check(p.length==1&&p[0].equals(Manifest.permission.RECORD_AUDIO)&&code==NotebookMicrophone.REQUEST,\"only microphone is requested\");requests++;}}static class Pref {boolean asked;boolean getBoolean(String k,boolean d){return asked;}Pref edit(){return this;}Pref putBoolean(String k,boolean v){asked=v;return this;}void apply(){}}",
            "interface Click{void click(Object d,int w);}static class AlertDialog {boolean showing;String message;Click positive;Consumer<Object> dismiss;static class Builder {final AlertDialog dialog=new AlertDialog();Builder(Activity a){}Builder setTitle(String t){return this;}Builder setMessage(String m){dialog.message=m;return this;}Builder setNegativeButton(String s,Click c){return this;}Builder setPositiveButton(String s,Click c){dialog.positive=c;return this;}AlertDialog create(){return dialog;}}void setOnDismissListener(Consumer<Object> c){dismiss=c;}void dismiss(){if(showing){showing=false;dismiss.accept(this);}}void accept(){positive.click(this,1);dismiss();}}static class NotebookUi {static AlertDialog shown;static void show(AlertDialog d){shown=d;d.showing=true;}}",
            "static class GeckoResult<T>{T value;static <T> GeckoResult<T> fromValue(T v){GeckoResult<T> r=new GeckoResult<>();r.value=v;return r;}}static class GeckoSession {interface PermissionDelegate {int PERMISSION_AUTOPLAY_AUDIBLE=5;interface Callback{void grant();void reject();}interface MediaCallback{void grant(MediaSource video,MediaSource audio);void reject();}class MediaSource {static final int TYPE_AUDIO=1,SOURCE_MICROPHONE=2;int type=TYPE_AUDIO,source=SOURCE_MICROPHONE;}class ContentPermission {static final int VALUE_ALLOW=1,VALUE_DENY=2;String uri;int permission=5;ContentPermission(String u){uri=u;}}default void onAndroidPermissionsRequest(GeckoSession s,String[] p,Callback c){}default void onMediaPermissionRequest(GeckoSession s,String u,MediaSource[] v,MediaSource[] a,MediaCallback c){}default GeckoResult<Integer> onContentPermissionRequest(GeckoSession s,ContentPermission p){return null;}}}",
            code("NotebookMicrophone"), code("NotebookBrowserMedia"),
            "static class Result implements GeckoSession.PermissionDelegate.Callback,GeckoSession.PermissionDelegate.MediaCallback {int grants,rejects;public void grant(){grants++;}public void grant(GeckoSession.PermissionDelegate.MediaSource video,GeckoSession.PermissionDelegate.MediaSource audio){check(video==null&&audio!=null,\"audio only source selected\");grants++;}public void reject(){rejects++;}}static final GeckoSession.PermissionDelegate.MediaSource[] AUDIO={new GeckoSession.PermissionDelegate.MediaSource()};static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static void request(NotebookBrowserMedia m,String uri,Result r){m.onMediaPermissionRequest(null,uri,null,AUDIO,r);}",
            "public static void run(){Activity a=new Activity();NotebookMicrophone mic=new NotebookMicrophone(a);mic.askOnce();check(a.requests==0,\"proactive request waits for resumed activity\");mic.resumed(true);check(a.requests==1,\"first browser entry proactively requests the microphone\");mic.resumed(false);a.granted=true;check(mic.permissionResult(NotebookMicrophone.REQUEST),\"our Android result is handled\");mic.resumed(true);mic.askOnce();check(a.requests==1,\"resume never repeats a resolved proactive request\");",
            "boolean[] foreground={true};String[] address={\"https://example.org/chat\"};NotebookBrowserMedia media=new NotebookBrowserMedia(a,mic,()->foreground[0],()->address[0]);Result first=new Result();request(media,address[0],first);check(first.grants==0&&first.rejects==0&&NotebookUi.shown.message.startsWith(\"https://example.org wants\"),\"app permission alone never grants a site's request\");NotebookUi.shown.accept();check(first.grants==1&&first.rejects==0,\"explicit document consent grants microphone input once\");Result repeat=new Result();request(media,address[0],repeat);check(repeat.grants==1,\"the same document may reopen its approved microphone\");check(media.onContentPermissionRequest(null,new GeckoSession.PermissionDelegate.ContentPermission(address[0])).value==1,\"voice response playback follows explicit consent\");",
            "Result cross=new Result();request(media,\"https://other.example/chat\",cross);check(cross.rejects==1,\"cross-origin frame cannot inherit top-level microphone permission\");Result video=new Result();media.onMediaPermissionRequest(null,address[0],AUDIO,AUDIO,video);check(video.rejects==1,\"undeclared camera requests remain denied\");foreground[0]=false;Result background=new Result();request(media,address[0],background);check(background.rejects==1,\"hidden pages cannot request capture\");foreground[0]=true;",
            "media.reset();Result navigation=new Result();request(media,address[0],navigation);AlertDialog old=NotebookUi.shown;media.reset();old.accept();check(navigation.rejects==1&&navigation.grants==0,\"navigation cancels an old consent prompt exactly once\");Result changed=new Result();request(media,address[0],changed);address[0]=\"https://other.example/\";NotebookUi.shown.accept();check(changed.rejects==1,\"origin is checked again when consent is accepted\");address[0]=\"https://example.org/chat\";Result canceled=new Result();request(media,address[0],canceled);media.cancelPrompt();check(canceled.rejects==1,\"leaving the window cancels outstanding site consent\");",
            "a.granted=false;Result bad=new Result();media.onAndroidPermissionsRequest(null,new String[]{\"android.permission.CAMERA\"},bad);check(bad.rejects==1&&a.requests==1,\"engine cannot request undeclared permissions\");Result enumeration=new Result();media.onAndroidPermissionsRequest(null,new String[]{Manifest.permission.RECORD_AUDIO},enumeration);check(enumeration.rejects==1&&a.requests==1,\"device enumeration cannot prompt for Android permission without an origin\");Result runtime=new Result();request(media,address[0],runtime);check(a.requests==2&&runtime.grants==0&&runtime.rejects==0,\"origin-specific website request retries Android permission before site consent\");mic.resumed(false);a.granted=true;mic.permissionResult(NotebookMicrophone.REQUEST);check(runtime.grants==0,\"Android callback waits until activity resumes\");media.reset();mic.resumed(true);check(runtime.rejects==1&&runtime.grants==0,\"document replaced during Android prompt is rejected\");",
            "Activity denied=new Activity();NotebookMicrophone deniedMic=new NotebookMicrophone(denied);deniedMic.resumed(true);deniedMic.askOnce();deniedMic.permissionResult(NotebookMicrophone.REQUEST);deniedMic.askOnce();check(denied.requests==1,\"proactive permission denial is not nagged on each entry\");int[] settled={0};deniedMic.resumed(false);deniedMic.request(value->{check(!value,\"destroyed activity rejects pending permission\");settled[0]++;});deniedMic.close();deniedMic.permissionResult(NotebookMicrophone.REQUEST);deniedMic.resumed(true);check(settled[0]==1,\"destroy settles callbacks once\");",
            "check(NotebookBrowserAddress.origin(\"HTTPS://EXAMPLE.org:443/path?q=one#x\").equals(\"https://example.org\"),\"default HTTPS ports share one origin\");check(NotebookBrowserAddress.origin(\"https://example.org:8443/path\").equals(\"https://example.org:8443\"),\"nondefault ports require separate consent\");for(String unsafe:new String[]{\"file:///page.html\",\"https://user:secret@example.org/\",\"javascript:alert(1)\"})check(NotebookBrowserAddress.origin(unsafe).isEmpty(),\"non-web and credential-bearing origins remain invalid\");address[0]=\"http://example.org/chat\";Result insecure=new Result();request(media,address[0],insecure);check(insecure.rejects==1&&insecure.grants==0,\"HTTP pages cannot request microphone access even when the origins match\");",
            "System.out.println(\"NotebookBrowserMedia: \"+checks+\" checks passed (production app/site permission, lifecycle, navigation, denial and origins).\");}}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.BrowserMediaFixture", fixture);
    }
}
